import{_ as a,o as r,c as l,ag as e}from"./chunks/framework.DXGyWiRo.js";const u=JSON.parse('{"title":"Согласие на обработку персональных данных","description":"","frontmatter":{},"headers":[],"relativePath":"consent-pd.md","filePath":"consent-pd.md","lastUpdated":null}'),o={name:"consent-pd.md"};function i(s,t,n,d,p,h){return r(),l("div",null,[...t[0]||(t[0]=[e('<h1 id="согласие-на-обработку-персональных-данных" tabindex="-1">Согласие на обработку персональных данных <a class="header-anchor" href="#согласие-на-обработку-персональных-данных" aria-label="Permalink to &quot;Согласие на обработку персональных данных&quot;">​</a></h1><p><strong>Оператор:</strong> ИП Ульянов Алексей Владимирович<br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></p><p><em>Редакция от 21 апреля 2026 г.</em></p><hr><div class="info custom-block"><p class="custom-block-title">Как принимается согласие</p><p>Настоящее согласие принимается путём совершения Пользователем акцептирующего действия: отметки чекбокса «Согласен с обработкой персональных данных» при регистрации, входе в систему или заполнении форм на gosms.ru и в приложении GoSMS Client.</p></div><p>Я, нижеподписавшийся (при электронном акцепте — Пользователь, осуществивший подтверждение), в соответствии с Федеральным законом от 27.07.2006 № 152-ФЗ «О персональных данных» (далее — ФЗ-152), свободно, своей волей и в своём интересе даю <strong>ИП Ульянову Алексею Владимировичу</strong> (ОГРНИП 321132600016985, далее — <strong>Оператор</strong>) согласие на обработку моих персональных данных на следующих условиях.</p><h2 id="_1-перечень-персональных-данных" tabindex="-1">1. Перечень персональных данных <a class="header-anchor" href="#_1-перечень-персональных-данных" aria-label="Permalink to &quot;1. Перечень персональных данных&quot;">​</a></h2><p>Согласие предоставляется на обработку следующих персональных данных:</p><ul><li>фамилия, имя, отчество (при наличии);</li><li>адрес электронной почты;</li><li>номер мобильного телефона;</li><li>IP-адрес устройства;</li><li>технические данные устройства (тип, модель, версия ОС, идентификаторы);</li><li>данные о геолокации (при явном предоставлении разрешения);</li><li>журналы активности в сервисе GoSMS;</li><li>иные данные, добровольно предоставленные Пользователем в формах регистрации, настройки профиля и обращений в поддержку.</li></ul><h2 id="_2-цели-обработки" tabindex="-1">2. Цели обработки <a class="header-anchor" href="#_2-цели-обработки" aria-label="Permalink to &quot;2. Цели обработки&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>Цель обработки</th></tr></thead><tbody><tr><td>1</td><td>Регистрация учётной записи и предоставление доступа к сервису GoSMS</td></tr><tr><td>2</td><td>Идентификация и аутентификация пользователя</td></tr><tr><td>3</td><td>Исполнение договора и предоставление услуг</td></tr><tr><td>4</td><td>Техническая поддержка пользователей</td></tr><tr><td>5</td><td>Направление уведомлений, связанных с работой сервиса</td></tr><tr><td>6</td><td>Обеспечение безопасности учётной записи</td></tr><tr><td>7</td><td>Улучшение функциональности сервиса на основе обезличенной аналитики</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Отдельное согласие</p><p>Согласие на получение <strong>рекламных и маркетинговых рассылок</strong> оформляется отдельно — см. <a href="/consent-marketing">Согласие на рекламные рассылки</a>.</p></div><h2 id="_3-перечень-деиствии-с-персональными-данными" tabindex="-1">3. Перечень действий с персональными данными <a class="header-anchor" href="#_3-перечень-деиствии-с-персональными-данными" aria-label="Permalink to &quot;3. Перечень действий с персональными данными&quot;">​</a></h2><p>Оператору предоставляется право осуществлять следующие действия (операции) с персональными данными:</p><ul><li>сбор, запись, систематизация;</li><li>накопление, хранение;</li><li>уточнение (обновление, изменение);</li><li>извлечение, использование;</li><li>передача (предоставление, доступ) — в объёме, предусмотренном <a href="/privacy-policy">Политикой конфиденциальности</a>;</li><li>обезличивание;</li><li>блокирование;</li><li>удаление, уничтожение.</li></ul><p>Обработка осуществляется с использованием средств автоматизации.</p><h2 id="_4-срок-деиствия-согласия" tabindex="-1">4. Срок действия согласия <a class="header-anchor" href="#_4-срок-деиствия-согласия" aria-label="Permalink to &quot;4. Срок действия согласия&quot;">​</a></h2><p>4.1. Согласие действует <strong>бессрочно</strong> — с момента его предоставления до момента отзыва.</p><p>4.2. Согласие также прекращает действие при удалении учётной записи Пользователя, за исключением данных, обработка которых обязательна в силу требований законодательства (налоговый и бухгалтерский учёт и т. д.).</p><h2 id="_5-право-на-отзыв-согласия" tabindex="-1">5. Право на отзыв согласия <a class="header-anchor" href="#_5-право-на-отзыв-согласия" aria-label="Permalink to &quot;5. Право на отзыв согласия&quot;">​</a></h2><p>5.1. Пользователь вправе в любое время отозвать согласие, направив письменное заявление на адрес <strong><a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></strong> с темой письма «Отзыв согласия на обработку персональных данных».</p><p>5.2. С момента получения заявления Оператор прекращает обработку персональных данных в течение <strong>30 (тридцати) рабочих дней</strong> и уничтожает данные, за исключением:</p><ul><li>данных, необходимых для исполнения обязательств, возникших до отзыва согласия;</li><li>данных, обработка которых предусмотрена законодательством РФ.</li></ul><p>5.3. Отзыв согласия не влияет на законность обработки, осуществлённой до его получения.</p><p>5.4. Отзыв согласия влечёт невозможность предоставления Сервиса — доступ к учётной записи будет прекращён.</p><h2 id="_6-передача-данных-третьим-лицам" tabindex="-1">6. Передача данных третьим лицам <a class="header-anchor" href="#_6-передача-данных-третьим-лицам" aria-label="Permalink to &quot;6. Передача данных третьим лицам&quot;">​</a></h2><p>6.1. Оператор вправе передавать персональные данные третьим лицам исключительно в объёме и на условиях, описанных в <a href="/privacy-policy">Политике конфиденциальности</a> (разд. 5).</p><p>6.2. Оператор не передаёт персональные данные в третьи страны без обеспечения надлежащего уровня их защиты.</p><h2 id="_7-права-субъекта-персональных-данных" tabindex="-1">7. Права субъекта персональных данных <a class="header-anchor" href="#_7-права-субъекта-персональных-данных" aria-label="Permalink to &quot;7. Права субъекта персональных данных&quot;">​</a></h2><p>В соответствии со ст. 14–17 ФЗ-152 Пользователь вправе:</p><ul><li>получать информацию о составе, целях и порядке обработки его данных;</li><li>требовать уточнения, блокирования или уничтожения данных, если они неполны, устарели, неточны, незаконно получены или не являются необходимыми для заявленной цели;</li><li>обжаловать действия или бездействие Оператора в Роскомнадзор (<a href="https://rkn.gov.ru" target="_blank" rel="noreferrer">rkn.gov.ru</a>) или в судебном порядке.</li></ul><h2 id="_8-контактные-данные-оператора" tabindex="-1">8. Контактные данные Оператора <a class="header-anchor" href="#_8-контактные-данные-оператора" aria-label="Permalink to &quot;8. Контактные данные Оператора&quot;">​</a></h2><p><strong>ИП Ульянов Алексей Владимирович</strong><br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></p>',33)])])}const _=a(o,[["render",i]]);export{u as __pageData,_ as default};
